func (s *Service) deliver(ctx context.Context, d store.Delivery) (bool, error) {
	ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
	e, eok := s.store.EventByID(d.EventID)
	if !ok || !ep.Enabled || !eok {
		errText := "the endpoint is disabled or was deleted"
		if !eok {
			errText = "the event no longer exists"
		}
		s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
			if d.Status == store.DeliveryPending {
				d.Status, d.Error, d.NextAttemptAt = store.DeliveryFailed, errText, nil
			}
			return nil
		})
		return false, nil
	}

