			for _, d := range e.Store.Deliveries(e.Acme.ID, ep.ID) {
				if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && d.NextAttemptAt.After(now) && d.NextAttemptAt.Before(next) {
					next = *d.NextAttemptAt
				}
			}
		}
		if !next.After(now) {
			return
		}
		e.Clock.Set(next)
	}
}

func TestRetrySchedule(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := newEndpoint(t, e, "https://hooks.acme.example/retry")
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	publish(t, e, "customer.created")

	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		d := onlyDelivery(t, e, ep)
		if d.Attempts != attempt || d.ResponseStatus != 500 || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(e.Clock.Now()) {
			t.Fatalf("after attempt %d: %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v, want failed with no next attempt", d)
			}
			break
		}
		wait := retryWaits[attempt-1]
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(wait)) {
			t.Fatalf("after attempt %d: %+v, want pending and next attempt %v later", attempt, d, wait)
		}
		e.Clock.Advance(wait - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was made %v early", attempt+1, time.Second)
		}
		e.Clock.Advance(time.Second)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed-for-good delivery was sent again: %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("%d requests, want 7", got)
	}
}

func TestFailedAttemptsAreRetried(t *testing.T) {
	for name, respond := range map[string]func(apitest.Request) (int, error){
		"no answer": func(apitest.Request) (int, error) { return 0, errors.New("connection refused") },
		"redirect":  func(apitest.Request) (int, error) { return http.StatusFound, nil },
	} {
		t.Run(name, func(t *testing.T) {
			e := apitest.New(t)
			ep := newEndpoint(t, e, "https://hooks.acme.example/fail")
			e.HTTP.Respond = respond
			publish(t, e, "customer.created")
			if n, err := e.Webhooks.RunDue(context.Background()); err != nil || n != 1 {
				t.Fatalf("RunDue = %d, %v", n, err)
			}
			d := onlyDelivery(t, e, ep)
			if d.Status != store.DeliveryPending || d.Error == "" || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(e.Clock.Now().Add(time.Minute)) {
				t.Fatalf("delivery = %+v, want pending with a retry in a minute", d)
			}
		})
	}
}

// timeoutDoer checks that each request has a deadline 10 seconds away, then times out.
type timeoutDoer struct{ t *testing.T }

func (d timeoutDoer) Do(req *http.Request) (*http.Response, error) {
	dl, ok := req.Context().Deadline()
	if !ok || time.Until(dl) > 10*time.Second {
		d.t.Errorf("request deadline = %v (set: %v), want within 10 seconds", time.Until(dl), ok)
	}
	return nil, context.DeadlineExceeded
}

func TestSlowAnswerFails(t *testing.T) {
	e := apitest.New(t)
	slow := webhooks.New(webhooks.Options{Store: e.Store, Clock: e.Clock, Doer: timeoutDoer{t}, Resolver: e.DNS, Mail: e.Mail})
	ep := newEndpoint(t, e, "https://hooks.acme.example/slow")
	if err := slow.Publish(context.Background(), e.Acme.ID, "customer.created", map[string]string{"id": "x"}); err != nil {
		t.Fatal(err)
	}
	if n, err := slow.RunDue(context.Background()); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v", n, err)
	}
	if d := onlyDelivery(t, e, ep); d.Status != store.DeliveryPending || d.Error == "" || d.ResponseStatus != 0 || d.Attempts != 1 {
		t.Fatalf("delivery = %+v, want a failed attempt that is retried", d)
	}
}

func TestRetryThenSucceeds(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := newEndpoint(t, e, "https://hooks.acme.example/recover")
	down := true
	e.HTTP.Respond = func(apitest.Request) (int, error) {
		if down {
			return http.StatusServiceUnavailable, nil
		}
		return http.StatusOK, nil
	}
	publish(t, e, "invoice.paid")
	if n, _ := e.Webhooks.RunDue(ctx); n != 1 {
		t.Fatalf("first RunDue = %d", n)
	}
	down = false
	e.Clock.Advance(time.Minute)
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("second RunDue = %d, %v", n, err)
	}
	d := onlyDelivery(t, e, ep)
	if d.Status != store.DeliverySucceeded || d.Attempts != 2 || d.ResponseStatus != 200 || d.Error != "" || d.NextAttemptAt != nil {
		t.Fatalf("delivery = %+v", d)
	}
	if raw, _ := json.Marshal(d); !strings.Contains(string(raw), `"next_attempt_at":null`) {
		t.Fatalf("JSON = %s, want next_attempt_at null", raw)
	}
	e.Clock.Advance(24 * time.Hour)
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a succeeded delivery was sent again: %d", n)
	}
}

func TestGoneDisablesEndpoint(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep := newEndpoint(t, e, "https://hooks.acme.example/gone")
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusGone, nil }
	publish(t, e, "customer.created")
	publish(t, e, "customer.updated")
	if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only one attempt: the endpoint is gone after it)", n, err)
	}
	if reqs := e.HTTP.Requests(); len(reqs) != 1 {
		t.Fatalf("%d requests, want 1", len(reqs))
	}
	got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID)
	if got.Enabled || got.DisabledReason != "gone" {
		t.Fatalf("endpoint = %+v, want disabled for gone", got)
	}
	attempts := 0
	for _, d := range e.Store.Deliveries(e.Acme.ID, ep.ID) {
		attempts += d.Attempts
		if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil || d.Error == "" {
			t.Fatalf("delivery = %+v, want failed for good", d)
		}
	}
	if attempts != 1 {
		t.Fatalf("attempts = %d, want 1", attempts)
	}
	e.Clock.Advance(time.Hour)
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 || len(e.HTTP.Requests()) != 1 {
		t.Fatalf("a delivery to a gone endpoint was sent")
	}
	if len(e.Mail.Messages()) != 0 {
		t.Fatalf("a 410 emailed the owners: %+v", e.Mail.Messages())
	}
}

func TestOwnersEmailedWhenDeliveryFailsForGood(t *testing.T) {
	e := apitest.New(t)
	e.AddMember(e.Acme, "second@acme.example", store.RoleOwner)
	e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	ep := newEndpoint(t, e, "https://hooks.acme.example/down")
	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusServiceUnavailable, nil }
	start := e.Clock.Now()
	publish(t, e, "customer.created")
	publish(t, e, "customer.updated")

	// The two deliveries fail for good at the same moment: the owners get one email each, not one per delivery.
	runUntil(t, e, start.Add(48*time.Hour), ep)
	msgs := e.Mail.Messages()
	if len(msgs) != 2 {
		t.Fatalf("%d emails, want 2 (one per owner): %+v", len(msgs), msgs)
	}
	to := map[string]bool{}
	for _, m := range msgs {
		to[m.To] = true
		if m.Subject != "Webhook endpoint failing: https://hooks.acme.example/down" {
			t.Fatalf("subject = %q", m.Subject)
		}
	}
	if !to["owner@acme.example"] || !to["second@acme.example"] || to["admin@acme.example"] {
		t.Fatalf("recipients = %v", to)
	}
	if got, _ := e.Store.WebhookEndpoint(e.Acme.ID, ep.ID); got.FailureMailedAt == nil {
		t.Fatal("the endpoint does not record the email")
	}
}

